export const SUBJECT_FLASHCARDS_STATS_SCENARIO: SubjectFlashcard[] = [
  { id: "stats-scenario-001", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 4, front: "某研究者从一所学校的 800 名高一学生中随机抽取 60 人，再把这 60 人随机分成两组各 30 人，一组用新的记忆方法，一组用传统方法，两周后测同一份记忆测验，基于该设计，最合适的推断是\nA. 有证据表明新法提高了成绩，结论可以推广到全国所有的高一学生\nB. 只有相关证据，因为两组各 30 人，人数太少不足以推断因果\nC. 只有相关证据，因为没有对同一名学生前后测量两次\nD. 有证据表明新法提高了成绩，结论只能推广到该校高一学生", back: "答案：D\n简析：先看抽样方式，随机抽样决定结论只可推广到被抽样的该校高一学生，再看分组方式，随机分配使新法与成绩之间可以作因果推断，样本量小或未做重复测量都不否定这两点，把结论扩大到全国则超出了抽样总体\n\n正确选项：有证据表明新法提高了成绩，结论只能推广到该校高一学生", source: "ai-mcq", verified: true },
  { id: "stats-scenario-002", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "为比较一种新止痛药与安慰剂的效果，研究者把 120 名慢性腰痛患者随机分成两组，一组服用新药，一组服用外观与味道相同的安慰剂，但发药的护士知道谁服的是新药，患者并不知道，关于该实验，说法正确的是\nA. 患者和护士都被盲，所以该实验不存在任何偏倚\nB. 患者被盲而护士未盲，护士的态度可能影响患者的报告\nC. 患者被盲而护士未盲，因此不能推断两组之间的因果差异\nD. 因为使用了安慰剂作为对照，所以该实验属于观察性研究", back: "答案：B\n简析：患者不知道分组属于单盲，护士知道谁用新药，她在给药和询问时的态度可能影响患者的疼痛报告，从而引入偏倚，随机分组仍使该实验能推断因果，安慰剂对照也不会使它变成观察性研究\n\n正确选项：患者被盲而护士未盲，护士的态度可能影响患者的报告", source: "ai-mcq", verified: true },
  { id: "stats-scenario-003", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某校想比较两种数学教学法对学生期末成绩的影响，先按入学成绩把学生分为高、中、低三个层次，再在每个层次内随机分配学生到两种教学法，最后比较期末成绩，这样安排的主要目的是\nA. 让两种教学法分到的学生人数始终保持完全相同\nB. 彻底消除入学成绩对期末成绩差异的影响\nC. 在控制成绩层次差异的同时比较两种教法\nD. 把入学成绩层次当成一个额外的处理变量", back: "答案：C\n简析：先分层再在每一层内随机分配属于区组设计，目的是把入学成绩带来的变异从误差中分离出来，使两种教法的比较更精确，区组变量不是处理变量，它只能减少而不能彻底消除成绩差异\n\n正确选项：在控制成绩层次差异的同时比较两种教法", source: "ai-mcq", verified: true },
  { id: "stats-scenario-004", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某电视台在晚间新闻后请观众通过热线或手机投票回答是否支持延长上学时间，共收到 4200 个回应，其中 71% 表示支持，对该调查结果最恰当的评价是\nA. 样本量很大，所以 71% 与总体比例几乎相同，不必担心\nB. 样本量很大，所以结果可推广到全体有手机的观众\nC. 样本量足以抵消自愿回应带来的偏差，结果仍可推广\nD. 属于自愿回应样本，热心观众更易回应，不能推广到总体", back: "答案：D\n简析：由观众自己决定是否回应构成自愿回应样本，热心或意见强烈者更可能回应，这属于系统性偏差，样本量再大也只减小随机波动，无法消除这种偏差，因此不能推广到所有观众\n\n正确选项：属于自愿回应样本，热心观众更易回应，不能推广到总体", source: "ai-mcq", verified: true },
  { id: "stats-scenario-005", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某观察性研究比较经常吃早餐与很少吃早餐的学生，发现前者的平均 GPA 明显更高，研究者据此建议所有学生每天都吃早餐以提高成绩，对该建议最恰当的批评是\nA. 可能有家庭收入等第三变量同时影响早餐与成绩\nB. 观察性研究无法提供两变量之间是否存在关联的信息\nC. 由于没有随机抽样，早餐习惯与成绩之间不存在任何关联\nD. 只要样本量足够大，相关关系就可以当成因果关系使用", back: "答案：A\n简析：观察性研究只能给出关联，早餐习惯可能与家庭收入与作息等第三变量同时变化，这些变量又影响成绩，相关不等于因果，但研究本身仍提供了两者存在关联的信息\n\n正确选项：可能有家庭收入等第三变量同时影响早餐与成绩", source: "ai-mcq", verified: true },
  { id: "stats-scenario-006", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某研究者想比较两种跑鞋对 5 公里成绩的影响，让 40 名跑者在两周内先后穿两种鞋各跑一次，穿鞋的顺序随机决定，然后比较每名跑者两次成绩之差，该设计\nA. 属于完全随机设计，因为跑者被随机分到了两个组\nB. 属于配对设计，但因为没有随机抽样，无法推断因果\nC. 属于配对设计，随机顺序能控制顺序及个体差异\nD. 属于观察性研究，因为每名跑者都充当了自己的对照", back: "答案：C\n简析：每名跑者先后接受两种处理并比较两次成绩之差，属于配对设计，随机决定顺序可平衡练习效应与疲劳等顺序影响，个体差异在差分中被消掉，因此即使没有随机抽样也能支持因果推断\n\n正确选项：属于配对设计，随机顺序能控制顺序及个体差异", source: "ai-mcq", verified: true },
  { id: "stats-scenario-007", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 1, front: "某连锁品牌收集了 12 家门店的日销量 y（杯）与每杯价格 x（元），得到回归直线 ŷ=320-18.5x，r²=0.64，对该回归系数的正确解释是\nA. 每杯价格每增加 1 元，日销量平均减少 0.64 杯\nB. 每杯价格增加 1 元，日销量平均减少 18.5 杯\nC. 价格与日销量的相关系数 r 就等于 -0.64\nD. 每杯价格上涨 1 元，日销量必定减少约 18.5 杯", back: "答案：B\n简析：斜率是 x 每增加 1 个单位时 y 的平均改变量，故价格每增加 1 元日销量平均减少 18.5 杯，0.64 是 r² 即决定系数而不是斜率，相关系数应为负的 0.8，平均减少也不等于每次必定减少\n\n正确选项：每杯价格增加 1 元，日销量平均减少 18.5 杯", source: "ai-mcq", verified: true },
  { id: "stats-scenario-008", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 1, front: "某品牌用各门店的每杯价格预测日销量，回归模型的判定系数 r²=0.64，对 r² 最恰当的解释是\nA. 价格可以解释日销量变异约 64%，其余来自其他因素\nB. 价格每变动 1 个单位，日销量就有 64% 的概率随之变化\nC. 价格与日销量的相关系数 r 也等于 0.64，方向为负\nD. 预测值与真实销量之间的平均差距约为 0.64 杯", back: "答案：A\n简析：r² 是回归平方和占总变异的比例，表示用价格预测日销量时约 64% 的销量变异可由回归解释，其余约 36% 来自价格以外的因素，r 应等于负的 0.8，r² 也不是预测误差的平均值\n\n正确选项：价格可以解释日销量变异约 64%，其余来自其他因素", source: "ai-mcq", verified: true },
  { id: "stats-scenario-009", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某研究者用 24 名学生的每周练习时间 x（小时）预测测验成绩 y（分），散点图中 x 最大的点明显低于整体趋势，去掉该点后斜率由 1.3 增为 2.1，r² 由 0.55 增为 0.81，关于该点，最恰当的说法是\nA. 该点一定是录入错误，所以在正式分析中应直接删掉\nB. 该点使 r² 变小，因此它一定是强影响点\nC. 该点明显影响斜率，报告中应说明并检查其影响\nD. 该点偏离直线，说明直线模型对这组数据不适用", back: "答案：C\n简析：该点位于 x 的远端且明显偏离趋势，去掉它后斜率由 1.3 变为 2.1、r² 由 0.55 变为 0.81，说明它对回归直线有较强影响，应报告并检查其影响，偏离趋势或使 r² 变小都不足以判定它是错误数据\n\n正确选项：该点明显影响斜率，报告中应说明并检查其影响", source: "ai-mcq", verified: true },
  { id: "stats-scenario-010", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某校用每天学习时间 x（小时）预测数学测验成绩 y（分），得到 ŷ=52+6.5x，数据中 x 的取值范围是 2 到 10 小时，某学生打算每天学习 20 小时，老师用该方程预测他的成绩，对此最恰当的评价是\nA. 预测值为 182 分，超过了满分，说明方程计算有误\nB. 只要 r² 接近 1，对任何 x 作出的预测都同样可靠\nC. 预测值很高，说明学习时间与成绩之间是负相关\nD. 20 小时远超数据范围，属于外推，预测结果不可靠", back: "答案：D\n简析：先把 20 小时代入方程得 52 加 130 等于 182 分，但原始数据的 x 只在 2 到 10 小时之间，用方程预测范围外的 x 属于外推，回归关系在数据范围外未必成立，r² 大只说明范围内拟合较好\n\n正确选项：20 小时远超数据范围，属于外推，预测结果不可靠", source: "ai-mcq", verified: true },
  { id: "stats-scenario-011", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某校调查了 200 名学生，100 名住校生中有 45 人每天锻炼，100 名走读生中有 30 人每天锻炼，比较两组每天锻炼的比例，最恰当的结论是\nA. 住校生每天锻炼的比例高 0.15，说明住校导致学生更爱锻炼\nB. 全部学生中每天锻炼的比例是 0.45，所以两组之间没有差异\nC. 住校生比例高 0.15，但不能据此说住校导致更爱锻炼\nD. 走读生中每天锻炼的比例为 0.70，明显高于住校生", back: "答案：C\n简析：住校生每天锻炼的比例为 45 除以 100 等于 0.45，走读生为 30 除以 100 等于 0.30，两者相差 0.15，但这是观察数据，不能据此说住校导致更爱锻炼，0.70 是走读生不锻炼的比例\n\n正确选项：住校生比例高 0.15，但不能据此说住校导致更爱锻炼", source: "ai-mcq", verified: true },
  { id: "stats-scenario-012", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某回归分析以 x 为横轴、以残差为纵轴作残差图，图中残差先随 x 增大而上升，随后又持续下降，呈明显的弯曲形状，最恰当的结论是\nA. 残差呈系统弯曲，说明直线模型可能不合适\nB. 残差出现弯曲，说明相邻残差之间存在自相关\nC. 残差的均值约为 0，说明直线模型是合适的\nD. 只要 r² 足够大，残差图的弯曲就可以忽略", back: "答案：A\n简析：残差随 x 先升后降形成系统弯曲，说明直线模型没能刻画 x 与 y 的关系，属于模型形式不合适，残差均值为 0 不能排除弯曲，弯曲也不是相邻残差自相关问题，r² 大也掩盖不了它\n\n正确选项：残差呈系统弯曲，说明直线模型可能不合适", source: "ai-mcq", verified: true },
  { id: "stats-scenario-013", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某工厂两条生产线中，甲线生产了全部产品的 60%，其次品率为 2%，乙线生产了 40%，其次品率为 5%，从当天全部产品中随机抽取一件，已知抽到的是次品，则它来自甲线的概率约为\nA. 约为 0.600，即直接使用甲线产量在全部产品中的比例\nB. 约为 0.375，即按两条线对次品的贡献比重重新分配\nC. 约为 0.012，即甲线产量比例与其次品率相乘的结果\nD. 约为 0.020，即乙线产品与次品同时发生的联合概率", back: "答案：B\n简析：甲线贡献次品的概率为 0.6 乘 0.02 等于 0.012，乙线为 0.4 乘 0.05 等于 0.020，次品来自甲线的条件概率为 0.012 除以 0.032 等于 0.375，0.600 是先验的产量比例，0.012 与 0.020 是联合概率而不是条件概率\n\n正确选项：约为 0.375，即按两条线对次品的贡献比重重新分配", source: "ai-mcq", verified: true },
  { id: "stats-scenario-014", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某球员每次罚球命中的概率为 0.7，各次罚球相互独立，他连续罚球直到第一次命中为止，则他恰好罚到第 4 次才首次命中的概率约为\nA. 0.0756，即四次罚球中恰好命中一次的概率\nB. 0.0189，即前三次未中且第四次命中\nC. 0.0270，即前三次都未命中的概率\nD. 0.4116，即四次罚球中恰好命中三次的概率", back: "答案：B\n简析：恰好第 4 次才首次命中要求前三次都未命中且第四次命中，概率为 0.3 的三次方乘 0.7 约等于 0.0189，0.0756 是四次中恰有一次命中的二项概率，0.4116 是恰有三次命中，0.0270 漏掉了最后一次必须命中\n\n正确选项：0.0189，即前三次未中且第四次命中", source: "ai-mcq", verified: true },
  { id: "stats-scenario-015", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某商店每天售出某商品的件数 X 的期望为 12 件、标准差为 3 件，每售出一件可获利 20 元，每天还需支付固定成本 200 元，若每天的净利润为 Y=20X-200 元，则 Y 的期望与标准差分别为\nA. 40 元和 3 元，因为售出件数的波动不会因获利改变\nB. 40 元和 60 元，因为标准差只受 20 倍的影响\nC. 240 元和 60 元，因为期望不必减去固定成本\nD. 40 元和 140 元，因为固定成本也要从标准差里扣除", back: "答案：B\n简析：先用期望的线性性质算 20 乘 12 减 200 等于 40 元，再看标准差只受乘数影响，加减常数不改变标准差，故标准差为 20 乘 3 等于 60 元，把标准差当成 3 是漏了乘 20，从标准差里扣除 200 则混淆了两类运算\n\n正确选项：40 元和 60 元，因为标准差只受 20 倍的影响", source: "ai-mcq", verified: true },
  { id: "stats-scenario-016", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某抽奖活动每次需要支付 5 元，设一次抽奖的奖金为 X 元，其分布为 P(X=0)=0.8，P(X=20)=0.15，P(X=100)=0.05，参加一次该活动的净收益的期望是\nA. 期望净收益为 8 元，即一次抽奖所得奖金的期望\nB. 期望净收益为 3 元，即中奖金额期望减去 5 元成本\nC. 期望净收益为 5 元，即每次都需支付的 5 元参与成本\nD. 期望净收益为 -3 元，即 5 元成本减去中奖金额期望", back: "答案：B\n简析：先求奖金的期望为 0.15 乘 20 加 0.05 乘 100 等于 8 元，再减去每次 5 元的参与成本，净收益的期望为 3 元，把 8 元当成净收益是漏掉成本，用 5 减 8 则把相减的方向弄反了\n\n正确选项：期望净收益为 3 元，即中奖金额期望减去 5 元成本", source: "ai-mcq", verified: true },
  { id: "stats-scenario-017", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某机器灌装饮料，单瓶容量 X 的期望为 500 毫升、标准差为 4 毫升，把 3 瓶装成一盒，各瓶容量相互独立，则一盒饮料总容量的标准差约为\nA. 约 6.93 毫升，因为各自方差相加后还要开方\nB. 约 12 毫升，因为瓶数增加时标准差也按倍数相加\nC. 约 4 毫升，因为装盒只改变均值而不改变标准差\nD. 约 48 毫升，因为应把 3 瓶的方差直接相加作为结果", back: "答案：A\n简析：独立随机变量之和的方差等于各自方差之和，即 3 乘 16 等于 48，标准差为 48 开方约 6.93 毫升，把标准差按倍数相加会得到 12，把方差直接当成标准差会得到 48，装盒同样会改变总容量的标准差\n\n正确选项：约 6.93 毫升，因为各自方差相加后还要开方", source: "ai-mcq", verified: true },
  { id: "stats-scenario-018", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某城市 40% 的居民支持某项提案，现从该市居民中随机抽取 100 人，用样本比例 p̂ 估计支持率，则 p̂ 的抽样分布\nA. 近似正态，均值 0.4，标准差约 0.049\nB. 近似正态，均值 0.4，标准差约 0.0024\nC. 不近似正态，因为总体比例 0.4 不等于 0.5\nD. 近似正态，均值 0.4，标准差约 0.0049", back: "答案：A\n简析：先查条件，np 等于 40 与 n 乘 (1-p) 等于 60 都至少为 10，故 p̂ 的抽样分布近似正态，均值为总体比例 0.4，标准差为 0.4 乘 0.6 除以 100 后开方约 0.049，0.0024 是方差，0.0049 是把分母 n 又开了一次方\n\n正确选项：近似正态，均值 0.4，标准差约 0.049", source: "ai-mcq", verified: true },
  { id: "stats-scenario-019", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 1, front: "某厂检验 H0: 电池平均寿命等于 40 小时，Ha: 平均寿命大于 40 小时，取显著性水平 α=0.05，若事实上电池平均寿命恰好就是 40 小时，而检验结果却拒绝了 H0，则这次判断\nA. 属于第二类错误，其概率就等于 α\nB. 属于第二类错误，其概率等于 1 减去 α\nC. 属于第一类错误，其概率等于 1 减去 β\nD. 属于第一类错误，其概率就等于 α", back: "答案：D\n简析：H0 为真而检验却拒绝 H0 属于第一类错误，它的概率由显著性水平控制所以等于 α，第二类错误是 H0 为假却没有拒绝，概率记为 β，1 减 β 是检验的功效而不是错误概率\n\n正确选项：属于第一类错误，其概率就等于 α", source: "ai-mcq", verified: true },
  { id: "stats-scenario-020", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某研究者对 H0: μ=10 与 Ha: μ≠10 做检验，得到 p 值等于 0.03，并与 α=0.05 比较，对该结果最恰当的解释是\nA. 若 H0 为真，出现当前或更极端结果的概率为 3%\nB. p 值 0.03 表示原假设 H0 为真的概率是 3%\nC. 拒绝 H0 后，原假设为假的概率约为 97%\nD. 因为 p 值小于 0.05，所以 H0 已被证明是假的", back: "答案：A\n简析：p 值是在 H0 为真的条件下得到当前或更极端样本结果的概率，0.03 小于 α 等于 0.05 所以拒绝 H0，p 值不是 H0 为真的概率，拒绝 H0 也不等于证明 H0 为假，只能说不利于 H0 的证据较强\n\n正确选项：若 H0 为真，出现当前或更极端结果的概率为 3%", source: "ai-mcq", verified: true },
  { id: "stats-scenario-021", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某研究者从某城市随机抽取居民样本，得到平均通勤时间的 95% 置信区间为 (28, 36) 分钟，对该区间的正确解释是\nA. 总体均值落在 28 到 36 分钟内的概率是 95%\nB. 该市约 95% 的居民通勤时间在 28 到 36 分钟之间\nC. 用这种方法构造的区间约 95% 能包含总体均值\nD. 重复抽样时约 95% 的样本均值会落在该区间内", back: "答案：C\n简析：置信区间的 95% 描述的是构造方法的长期表现，即反复抽样所构造的区间中约 95% 会包含总体均值，对已经算出的这一个区间只能说它包含或不包含总体均值，总体均值不是随机变量，该区间也不描述个体居民\n\n正确选项：用这种方法构造的区间约 95% 能包含总体均值", source: "ai-mcq", verified: true },
  { id: "stats-scenario-022", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某校声称有 60% 的学生乘公共交通上学，为检验这一说法，研究者随机抽取了 80 名学生，其中 40 人乘公共交通，设 p 为学生中乘公共交通的真实比例，关于该检验最恰当的是\nA. 应改用双比例 z 检验，因为把 80 人分成乘与不乘两组\nB. 近似正态条件不满足，因为 p̂=0.5 与假设值 0.6 不相等\nC. 条件满足，z 约为 -1.83，单侧 p 值约 0.034\nD. 条件满足，z 约为 -1.83，双侧 p 值约 0.068", back: "答案：D\n简析：先用假设值查条件，80 乘 0.6 等于 48 与 80 乘 0.4 等于 32 都至少为 10，再用 p̂ 等于 0.5 算得 z 约 -1.83，因为备择假设是双侧所以 p 值约为 0.068，0.034 是把双侧检验错当成单侧的结果，条件不满足的说法也不成立\n\n正确选项：条件满足，z 约为 -1.83，双侧 p 值约 0.068", source: "ai-mcq", verified: true },
  { id: "stats-scenario-023", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某研究随机调查了 300 名成年人，记录其最高学历（高中及以下、本科、研究生）与是否每周经常运动，想判断两个变量是否有关，列联表检验中所有期望频数都不小于 6.2，最恰当的做法是\nA. 用卡方独立性检验，期望频数条件已经满足\nB. 用卡方拟合优度检验，因为它能比较两个分类变量\nC. 用卡方独立性检验，但期望频数太小，条件不满足\nD. 用双比例 z 检验，因为两个变量都有两个以上类别", back: "答案：A\n简析：两个分类变量之间的关联用卡方独立性检验，学历分成三类无法用只适用于 2×2 表的双比例 z 检验，卡方拟合优度检验只处理一个变量的分布，所有期望频数都不小于 6.2 已满足至少为 5 的条件\n\n正确选项：用卡方独立性检验，期望频数条件已经满足", source: "ai-mcq", verified: true },
  { id: "stats-scenario-024", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某研究把 400 名学生按是否参加课后辅导与期末是否及格整理成 2×2 列联表，卡方独立性检验得到 χ²=6.74，df=1，p 值=0.0094，取 α=0.05，正确的结论是\nA. 在 α=0.05 下拒绝独立假设，两变量存在关联\nB. p 值 0.0094 表示两个变量独立的概率只有 0.0094\nC. p 值很小，说明两个变量之间存在很强的因果联系\nD. 在 α=0.05 下不能拒绝独立假设，因为 χ² 值不够大", back: "答案：A\n简析：先由 χ² 等于 6.74 与 df 等于 1 得到 p 值约 0.0094，再与 α 等于 0.05 比较，p 值小于 α 故拒绝独立假设，结论是两个变量存在关联，卡方检验只说明关联而不说明因果，p 值也不是独立假设为真的概率\n\n正确选项：在 α=0.05 下拒绝独立假设，两变量存在关联", source: "ai-mcq", verified: true },
  { id: "stats-scenario-025", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某研究用 30 个城市的数据，以人均收入 x（千元）预测人均消费 y（千元），回归输出为常数项 1.35、斜率 0.72、斜率的标准误 0.24、斜率检验的 p 值 0.006，取 α=0.05，正确的结论是\nA. 斜率 0.72 表示收入与消费的相关系数也是 0.72\nB. 因为 p 值很小，说明模型能解释 99.4% 的消费变异\nC. 收入每增加 1 千元，消费一定提高 0.72 千元\nD. 有证据表明总体斜率不为 0，两变量存在线性关系", back: "答案：D\n简析：先算斜率检验的 t 值等于 0.72 除以 0.24 等于 3.0，df 为 28 时对应双侧 p 值约 0.006，小于 0.05 故拒绝总体斜率为 0 的原假设，说明有证据支持收入与消费之间的线性关系，p 值小不代表解释比例大，回归斜率也不等于相关系数\n\n正确选项：有证据表明总体斜率不为 0，两变量存在线性关系", source: "ai-mcq", verified: true },
  { id: "stats-scenario-026", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某校共有 1200 名学生，其中高一 500 人、高二 400 人、高三 300 人。研究者想估计全校学生平均每天的睡眠时间，他先按年级分成三层，再在各层内按人数比例随机抽取共 120 人。与直接从 1200 人中简单随机抽取 120 人相比，这样分层抽样的主要好处是\nA. 样本中各年级的比例与全校一致，且层内差异较小，估计的变异更小\nB. 各年级被抽到的人数完全相同，都是 40 人，使样本在各层之间更均衡\nC. 层内可以用便利抽样代替随机抽样，因为分层本身已经保证了代表性\nD. 结论可以推广到全国所有高中生，因为各年级的比例已经被控制住", back: "答案：A\n简析：按比例分层后各层抽样数为 50、40、30，样本结构与全校一致，层内差异小使估计的变异更小，故 A 正确，40 人是等额分配而不是按比例分配，层内仍必须随机抽取而不能用便利抽样，分层只保证对本校的代表性，不能把结论推广到全国高中生\n\n正确选项：样本中各年级的比例与全校一致，且层内差异较小，估计的变异更小", source: "ai-mcq", verified: true },
  { id: "stats-scenario-027", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某工厂每天生产 2000 件零件，质检员按生产顺序把零件编号 1 至 2000，先在 1 至 20 中随机取一个起点，再每隔 20 件抽取一件，共检查 100 件，结果次品率明显低于以往记录。关于该抽样方法，最恰当的说法是\nA. 这是整群抽样，因为每隔 20 件相当于把连续 20 件产品看成一个群\nB. 这是系统抽样，若次品出现周期性且与间隔 20 重合则可能漏检\nC. 这是分层抽样，因为产品按编号被分为 20 层后每层抽一件，各件产品的入选概率并不相等\nD. 这是简单随机抽样，因为起点是随机产生的，所以样本一定无偏", back: "答案：B\n简析：随机起点加固定间隔 20 属于系统抽样，若次品出现周期性且与间隔重合就会系统性漏检，故 B 正确，把连续 20 件看成一群是整群抽样，产品并没有先分层再抽样，所以 C 的说法不成立，起点随机时每件产品被抽中的概率确实都等于 1/20，但样本只能来自 20 个起点，不是简单随机样本：各单位不独立，且次品呈周期 20 时会出现系统性偏差\n\n正确选项：这是系统抽样，若次品出现周期性且与间隔 20 重合则可能漏检", source: "ai-mcq", verified: true },
  { id: "stats-scenario-028", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某网站在首页设置投票按钮，两天内收到 6800 份回应，其中 82% 反对新建垃圾处理厂；同时研究者在同一网站的注册用户中随机抽取 400 人做电话访谈，其中 46% 反对。关于两个结果差异的解释，最恰当的是\nA. 6800 人的样本远大于 400 人，所以 82% 更接近真实比例\nB. 首页投票存在偏差，所以随机抽取的 400 人访谈结果也同样不可信\nC. 首页投票属于自愿回应样本，热心者更愿参与，样本量再大也难消除偏差\nD. 两个结果的差异说明居民的意见在两天内发生了明显变化，因此都有效", back: "答案：C\n简析：首页投票由观众自愿参与，意见强烈者更可能回应，属系统偏差，样本量增大只减小随机波动，不能消除这种偏差，故 C 正确，6800 人不能使 82% 更接近真实比例，把首页投票的偏差推广到随机抽取的 400 人访谈样本上并无依据，两天内的意见也不会改变这么快\n\n正确选项：首页投票属于自愿回应样本，热心者更愿参与，样本量再大也难消除偏差", source: "ai-mcq", verified: true },
  { id: "stats-scenario-029", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某药厂试验一种新的抗过敏药，随机把 200 名患者分成两组，一组服用新药，另一组服用外观与味道相同的安慰剂，患者和评估症状的医生都不知道分组。结果新药组症状评分平均下降 4.2 分，安慰剂组下降 1.6 分。由该实验最恰当的结论是\nA. 两组差异 2.6 分说明新药有效，且结论可推广到全国所有过敏患者\nB. 患者与医生都被盲，说明实验不存在任何偏倚，差异完全来自药物\nC. 差异 2.6 分且随机分配，可推断新药对这些患者有因果作用\nD. 安慰剂组症状也下降 1.6 分，说明安慰剂有疗效而实验缺少对照", back: "答案：C\n简析：随机分配加安慰剂对照加双盲，两组差异 2.6 分可作因果解释，但只适用于参与实验的患者，故 C 正确，没有从总体随机抽样不能推广到全国过敏患者，双盲只控制部分偏倚而不能消除全部偏倚，安慰剂组下降属安慰剂效应，实验仍有对照组\n\n正确选项：差异 2.6 分且随机分配，可推断新药对这些患者有因果作用", source: "ai-mcq", verified: true },
  { id: "stats-scenario-030", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某农业研究站想比较两种肥料对小麦产量的影响，因为试验田的肥力差异较大，先把 24 块田按肥力分成 8 个区组，每组 3 块肥力接近的田，再在每个区组内随机把 3 块田分给肥料甲、肥料乙和对照。与把 24 块田完全随机分成三组相比，这样设计的主要好处是\nA. 使每个处理都分到同样多的田，因此实验不再需要随机分配\nB. 把肥力当成第二个处理变量，从而可以比较肥料与肥力的交互作用\nC. 区组设计能彻底消除肥力差异，使产量差异完全来自两种肥料\nD. 把肥力差异从误差中分离出来，使处理的差异更容易被检测到", back: "答案：D\n简析：区组把肥力引起的变异分离出来，减小误差使处理差异更容易被检测，故 D 正确，区组设计仍需随机分配，肥力是区组变量而不是第二个处理变量，区组只能减小而不能彻底消除肥力差异\n\n正确选项：把肥力差异从误差中分离出来，使处理的差异更容易被检测到", source: "ai-mcq", verified: true },
  { id: "stats-scenario-031", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某研究者想比较两种键盘布局对打字速度的影响，他招募 30 名打字员，每人在两周内分别使用两种布局各打同一篇文章一次，使用顺序由随机数决定，最后分析每人两次用时之差。关于该设计与推断，最恰当的是\nA. 属于配对设计，个体差异在差值中被消去，随机顺序控制了练习效应\nB. 属于完全随机设计，因为每名打字员的先后顺序都由随机数决定\nC. 属于观察性研究，因为每名打字员都先后使用了两种不同的键盘布局\nD. 属于配对设计，但因为打字员不是随机抽样而来，故不能对结果作任何推断", back: "答案：A\n简析：同一批人先后接受两种处理并分析差值属于配对设计，个体差异在差值中消去，随机顺序平衡了练习与疲劳效应，故 A 正确，完全随机设计要把个体分到不同组，本设计每人都接受两种处理，不是观察性研究，没有随机抽样只影响结论的推广范围，不影响对这批人的因果推断\n\n正确选项：属于配对设计，个体差异在差值中被消去，随机顺序控制了练习效应", source: "ai-mcq", verified: true },
  { id: "stats-scenario-032", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 4, front: "某市卫生部门从全市成年人中随机抽取 1500 人做调查，发现每周喝 3 次以上含糖饮料的人中患高血压的比例为 21%，而很少喝的人中为 12%。研究者据此建议市民少喝含糖饮料以降低高血压风险。对该建议最恰当的批评是\nA. 因为调查是随机抽样，结论既能推广到全市成年人，也能说明含糖饮料导致高血压\nB. 因为不是随机分配，喝饮料多的人可能在其他方面也有差别，不能推断因果\nC. 因为样本量达到 1500 人，随机波动已经很小，所以其中的因果关系是可靠的\nD. 因为没有随机分配，所以连全市成年人患高血压的比例也无法估计", back: "答案：B\n简析：随机抽样只保证可推广，随机分配才支持因果，喝饮料多的人可能同时有其他差别，这些第三变量混杂了比较，故 B 正确，随机抽样不能替代随机分配，样本量大只减小随机波动不能消除混杂，随机抽样恰恰使全市比例可以被估计\n\n正确选项：因为不是随机分配，喝饮料多的人可能在其他方面也有差别，不能推断因果", source: "ai-mcq", verified: true },
  { id: "stats-scenario-033", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 4, front: "某大学调查申请者的录取情况，按申请院系整理如下：竞争激烈的甲院系中，男性 20 人申请录取 4 人，女性 80 人申请录取 24 人；录取较宽松的乙院系中，男性 80 人申请录取 64 人，女性 20 人申请录取 17 人。对这两个院系的数据最恰当的分析是\nA. 男性总体录取率 68% 高于女性 41%，说明该校在录取中明显偏向男性\nB. 甲院系男性录取率 20% 低于女性 30%，说明该校在录取中偏向女性\nC. 女性在两个院系的录取率都更高，说明女性总体录取率也一定高于男性\nD. 女性在两个院系的录取率都更高，总体差异主要来自申请院系的结构差异", back: "答案：D\n简析：甲院系女性录取率 24/80=30% 高于男性 4/20=20%，乙院系女性 17/20=85% 高于男性 64/80=80%，但男性总体上多申请了录取宽松的乙院系，故总体 68% 与 41% 的差异主要来自院系结构，D 正确，A 用边际比例得出偏向男性的结论忽略了院系这一混杂变量，B 只看甲院系就得出全校偏向女性，忽略了男性更多申请录取宽松的乙院系；女性总体录取率 41% 反而低于男性 68%，C 与数据相反\n\n正确选项：女性在两个院系的录取率都更高，总体差异主要来自申请院系的结构差异", source: "ai-mcq", verified: true },
  { id: "stats-scenario-034", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某市两所中学高三数学模拟考成绩（满分 150）如下：甲校 200 人，中位数 96，四分位距 18，均值 98，标准差 12，最高分 150；乙校 200 人，中位数 96，四分位距 26，均值 92，标准差 20，最低分 22。比较两校成绩的分布，最恰当的是\nA. 两校成绩的中位数都是 96，说明两校分布形状也完全相同\nB. 乙校成绩的标准差更大，说明乙校学生的平均成绩也高于甲校学生\nC. 甲校的四分位距更小，说明其中间一半学生的成绩比乙校更集中\nD. 甲校有 150 分的最高分，说明甲校高分学生的比例明显高于乙校", back: "答案：C\n简析：四分位距描述中间一半数据的离散程度，甲校 18 小于乙校 26，故甲校中间一半成绩更集中，C 正确，中位数相同不代表形状相同，标准差大与均值高低是两件事，乙校均值 92 反而更低，单个最高分不能说明高分学生的比例\n\n正确选项：甲校的四分位距更小，说明其中间一半学生的成绩比乙校更集中", source: "ai-mcq", verified: true },
  { id: "stats-scenario-035", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某媒体为展示某市房价一年内从每平方米 3.0 万元涨到 3.6 万元，把所画图表的纵轴起点设为 2.8 万元，并把表示房价的柱形的高度和宽度都放大为原来的 2 倍。关于该图，最恰当的评价是\nA. 实际涨幅约 20%，但截断纵轴并放大柱形宽高会夸大视觉上的涨幅\nB. 实际涨幅约 20%，纵轴起点设为 2.8 万元说明图中的数据本身有误\nC. 柱形宽高都放大 2 倍后视觉面积也放大 2 倍，与实际涨幅正好一致\nD. 只要图中标出了纵轴起点，截断纵轴就不会对读者造成任何误导", back: "答案：A\n简析：纵轴从 2.8 万元起会把 0.6 万元的差异在视觉上放大，宽高各放大 2 倍使面积变为 4 倍而涨幅仍是 20%，属典型的误导性图形，故 A 正确，数据本身没有错，面积放大 2 倍与实际涨幅不一致，标出起点也不能消除截断纵轴带来的夸大效果\n\n正确选项：实际涨幅约 20%，但截断纵轴并放大柱形宽高会夸大视觉上的涨幅", source: "ai-mcq", verified: true },
  { id: "stats-scenario-036", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某型号电池的寿命近似服从正态分布，均值为 500 小时，标准差为 40 小时。查标准正态表得 P(Z<0.5)=0.6915，P(Z<1.25)=0.8944。该型号电池寿命在 520 小时到 550 小时之间的比例约为\nA. 约 0.692，即直接取 520 小时对应的累积比例 0.6915\nB. 约 0.894，即直接取 550 小时对应的累积比例 0.8944\nC. 约 0.106，即用 1 减去 550 小时对应的累积比例 0.8944\nD. 约 0.203，即把 550 小时与 520 小时对应的累积比例相减", back: "答案：D\n简析：先算 z1=(520-500)/40=0.5 与 z2=(550-500)/40=1.25，再取两累积比例之差 0.8944-0.6915=0.2029，故 D 正确，0.6915 是 520 小时以下的比例，0.8944 是 550 小时以下的比例，1-0.8944=0.1056 是 550 小时以上的比例，三者都只用了单个边界\n\n正确选项：约 0.203，即把 550 小时与 520 小时对应的累积比例相减", source: "ai-mcq", verified: true },
  { id: "stats-scenario-037", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某公司称其客服电话在 30 秒内接通的比率为 0.35，质量部门每天随机抽查 200 个来电记录，用样本比例 p̂ 估计该比率。关于 p̂ 的抽样分布，最恰当的是\nA. 均值约 0.35，标准差约 0.0011，因为把方差直接当成了标准差\nB. 均值约 0.35，标准差约 0.034，因两个期望次数都大于 10 故近似正态\nC. 均值约 0.35，标准差约 0.034，但分布一定右偏，因为总体比例小于 0.5\nD. 均值约 0.35，标准差约 0.48，因为计算标准差时不必除以样本量", back: "答案：B\n简析：先检查 np=70 与 n(1-p)=130 都大于 10，故分布近似正态，均值等于总体比例 0.35，标准差为根号下 0.35 乘 0.65 除以 200 约等于 0.0337，B 正确，0.0011 是方差，比例不等于 0.5 并不会使分布右偏，不除以样本量会得到 0.477\n\n正确选项：均值约 0.35，标准差约 0.034，因两个期望次数都大于 10 故近似正态", source: "ai-mcq", verified: true },
  { id: "stats-scenario-038", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某市居民月收入的分布明显右偏，总体均值为 6000 元，标准差为 2400 元。研究者用计算机模拟从该市随机抽取样本并计算样本均值 x̄，分别做了样本量为 4 与样本量为 100 的两组模拟。关于 x̄ 的抽样分布，最恰当的是\nA. 样本量为 4 时 x̄ 的分布也一定近似正态，因为总体均值恰好为 6000 元\nB. 样本量越大 x̄ 就越接近 6000 元，说明样本量较小时 x̄ 本身是有偏的\nC. 两种样本量下 x̄ 的均值都约 6000 元，样本量为 100 时更窄更接近正态\nD. 样本量为 100 时 x̄ 的标准差仍约为 2400 元，因为收入的总体标准差不变", back: "答案：C\n简析：样本均值对任何样本量都是总体均值的无偏估计，故两组模拟中 x̄ 的均值都约为 6000 元，n=100 时标准误 2400 除以 10 等于 240 远小于 n=4 时的 1200，且由中心极限定理分布更接近正态，C 正确，样本量为 4 时右偏总体下的抽样分布不会近似正态，样本量小时 x̄ 仍然无偏，n=100 时标准差应约为 240 元而不是 2400 元\n\n正确选项：两种样本量下 x̄ 的均值都约 6000 元，样本量为 100 时更窄更接近正态", source: "ai-mcq", verified: true },
  { id: "stats-scenario-039", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某校随机调查了 400 名学生，其中 248 人支持延长图书馆的开放时间。研究者算得样本比例 p̂=0.62，标准误约为 0.0243，95% 置信区间约为 (0.572, 0.668)。对该区间最恰当的解释是\nA. 全校约 95% 的学生支持延长开放时间，其比例在 0.572 到 0.668 之间\nB. 反复抽样时，用同样方法构造的区间约有 95% 会包含全校真实的那个比例\nC. 全校真实的支持比例落在 0.572 到 0.668 之间的概率是 95%\nD. 样本比例 0.62 落在这个区间内的概率为 95%，说明该估计很可靠", back: "答案：B\n简析：95% 描述的是构造区间的长期表现，反复抽样所得区间的约 95% 会包含总体真实比例，B 正确，A 把区间说成个体学生的比例范围，C 把总体参数当成随机变量，D 样本比例 0.62 本身是区间的中心，其落入概率为 1\n\n正确选项：反复抽样时，用同样方法构造的区间约有 95% 会包含全校真实的那个比例", source: "ai-mcq", verified: true },
  { id: "stats-scenario-040", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某工厂随机抽取 25 根钢缆测量抗拉强度，样本均值为 820 牛、标准差为 60 牛，自由度 24 时 t*=2.064，95% 置信区间的边际误差约为 24.8 牛。若把样本量改为 100 根，且样本标准差仍约为 60 牛、t* 仍取 2.064，则新的边际误差约为\nA. 约 24.8 牛，因为样本量只改变区间的中心位置，不改变区间宽度\nB. 约 6.2 牛，因为边际误差与样本量成反比，样本量变为 4 倍则缩为四分之一\nC. 约 49.6 牛，因为样本量增大后标准误也随之变成原来的 2 倍\nD. 约 12.4 牛，因为边际误差与样本量的平方根成反比，故恰好减为一半", back: "答案：D\n简析：标准误为 60 除以 25 的平方根等于 12，边际误差为 2.064 乘 12 约 24.8；样本量变为 100 时标准误为 60 除以 10 等于 6，边际误差约 12.4，即边际误差与样本量的平方根成反比，D 正确，边际误差随样本量改变而不是只改变区间中心，与样本量成反比会得到 6.2，样本量增大时标准误应变小而不是变为 2 倍\n\n正确选项：约 12.4 牛，因为边际误差与样本量的平方根成反比，故恰好减为一半", source: "ai-mcq", verified: true },
  { id: "stats-scenario-041", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某校去年有 55% 的学生经常参加体育锻炼。今年该校随机调查 150 名学生，其中 96 人经常参加。研究者检验今年的比例是否与去年的 55% 不同，取 α=0.05。根据该检验，最恰当的结论是\nA. z 约为 2.22，双侧 p 值约为 0.027，拒绝 H0，说明比例确实已改变\nB. z 约为 2.22，p 值约为 0.013，因为这里应该做的是单侧检验\nC. 条件不满足，因为 p̂=0.64 与假设值 0.55 相差 0.09，偏离过大\nD. z 约为 2.22，p 值约为 0.027，说明 H0 为真的概率约为 0.027", back: "答案：A\n简析：由 p̂=96/150=0.64，用假设值算标准误 0.55 乘 0.45 除以 150 后开方约 0.0406，z 约 2.22，双侧 p 值约 0.027 小于 0.05，故拒绝 H0 且备择是双侧，A 正确，题目问是否不同应作双侧检验，0.013 是单侧 p 值，条件由 np0=82.5 与 n(1-p0)=67.5 都大于 10 而满足，p 值也不是 H0 为真的概率\n\n正确选项：z 约为 2.22，双侧 p 值约为 0.027，拒绝 H0，说明比例确实已改变", source: "ai-mcq", verified: true },
  { id: "stats-scenario-042", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某品牌声称其瓶装果汁的平均净含量为 500 毫升。质检员随机抽取 16 瓶，测得样本均值 494 毫升、标准差 8 毫升，且样本直方图大致对称、无异常值。检验平均含量是否不足，取 α=0.05。已知 df=15 时单侧面积 0.0123 对应 t=-2.5，单侧面积 0.0045 对应 t=-3.0。根据该检验，最恰当的结论是\nA. t 约为 -3.00，双侧 p 值约为 0.009，在 α=0.05 下不能拒绝 H0\nB. t 约为 -0.75，因为应把 6 毫升的差值直接除以标准差 8 毫升\nC. t 约为 -3.00，单侧 p 值约为 0.0045，故拒绝 H0，认为含量不足\nD. t 约为 -3.00，单侧 p 值约为 0.0045，说明含量不足的概率是 0.45%", back: "答案：C\n简析：小样本且总体标准差未知，用 t 检验，样本大致对称、无异常值使正态性条件成立；t=(494-500) 除以 (8 除以 4) 等于 -6 除以 2 等于 -3.0，备择为单侧，df=15 时单侧 p 值约 0.0045 小于 0.05，故拒绝 H0 认为平均含量不足，C 正确，0.009 是双侧 p 值，方向不对，把 6 除以 8 漏掉了除以样本量的平方根，p 值不是平均含量不足这一事件的概率\n\n正确选项：t 约为 -3.00，单侧 p 值约为 0.0045，故拒绝 H0，认为含量不足", source: "ai-mcq", verified: true },
  { id: "stats-scenario-043", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 2, front: "某厂检验 H0：新工艺没有降低废品率（废品率仍为 8%），Ha：废品率低于 8%，取 α=0.05。若真实废品率为 5%，该检验的功效为 0.80。关于该检验的两类错误与功效，最恰当的是\nA. 由于功效为 0.80，说明新工艺真正有效的概率就是 0.80，与样本无关\nB. 若新工艺无效，错误认为有效的概率为 0.20；若真实为 5%，漏检概率为 0.05\nC. 只要不断增大样本量，就能把两类错误的概率都降为零，使功效等于 1\nD. 若新工艺无效，错误认为有效的概率为 0.05；若真实为 5%，漏检为 0.20", back: "答案：D\n简析：α=0.05 是 H0 为真时误认为有效的概率，即第一类错误概率；功效 0.80 表示备择成立时正确拒绝的概率，故第二类错误概率为 1-0.80=0.20，D 正确，功效不是新工艺有效的概率，0.20 与 0.05 两个数字被对调，增大样本量只能减小第二类错误而不能把两类错误都降为零\n\n正确选项：若新工艺无效，错误认为有效的概率为 0.05；若真实为 5%，漏检为 0.20", source: "ai-mcq", verified: true },
  { id: "stats-scenario-044", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某公司对 20 万名用户做随机试验，比较两种界面设计的下单率：旧界面为 12.2%，新界面为 12.5%，检验的 p 值为 0.002，取 α=0.05。改版所需的开发成本远高于 0.3 个百分点带来的收益。对该结果最恰当的解释是\nA. 因为 p 值只有 0.002，说明这个差异一定有实际意义，公司应立即改版\nB. 差异在统计上显著，但是否值得改版还要看差异的实际大小与改版的成本\nC. 因为差异只有 0.3 个百分点，所以这个统计显著性一定是计算出现了错误\nD. 大样本会使 p 值变得很小，因此这类大样本检验的结论没有任何价值", back: "答案：B\n简析：p 值小于 α 只说明差异不太可能由随机波动造成，样本极大时很小的差异也会显著，是否有实际意义还要看差异大小、收益与成本，B 正确，统计显著不等于有实际意义，差异小也不意味着计算错误，大样本检验依然提供了关于效应是否存在的证据\n\n正确选项：差异在统计上显著，但是否值得改版还要看差异的实际大小与改版的成本", source: "ai-mcq", verified: true },
  { id: "stats-scenario-045", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某校调查 300 名学生最喜欢的午餐类型，四类人数依次为 90、85、65、60，学校声称四类受欢迎程度相同。已知 df=3 时卡方值 7.81 对应右侧面积 0.05，9.35 对应右侧面积 0.025。该拟合优度检验的结论是\nA. 期望频数均为 75，χ² 约为 8.67，p 值在 0.025 与 0.05 之间，故拒绝该校说法\nB. 期望频数均为 75，χ² 约为 8.67，df 应为 4，p 值大于 0.05，不能拒绝该校说法\nC. 期望频数均为 75，χ² 约为 8.67，p 值约为 0.017，因为应把 χ² 再除以 2 后查表\nD. 期望频数应取每类观测值 90 等，χ² 约为 0.029，说明四类人数与学校说法一致", back: "答案：A\n简析：各类期望频数都是 300 除以 4 等于 75，χ²=(90-75)²/75+(85-75)²/75+(65-75)²/75+(60-75)²/75=3+1.33+1.33+3 约 8.67，df=4-1=3，8.67 落在 7.81 与 9.35 之间故 p 值在 0.025 与 0.05 之间，拒绝四类相同的原假设，A 正确，卡方拟合优度检验的自由度是类别数减 1 而不是 4，把 χ² 除以 2 没有依据，期望频数应由总数乘假设比例算出，而不是直接取某类的观测值\n\n正确选项：期望频数均为 75，χ² 约为 8.67，p 值在 0.025 与 0.05 之间，故拒绝该校说法", source: "ai-mcq", verified: true },
  { id: "stats-scenario-046", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某研究在两个城市各随机调查 200 名居民是否支持某项政策：甲市 120 人支持、80 人反对，乙市 90 人支持、110 人反对。已知 df=1 时卡方值 3.84 对应右侧面积 0.05，6.63 对应右侧面积 0.01。关于该检验，最恰当的是\nA. 四个格子的期望频数都取 100，χ² 约为 16.0，又按 df=2 查表认为 p 值大于 0.01，故不能拒绝\nB. 甲市支持的期望频数为 105，χ² 约 9.02，df 应为 3，p 值在 0.01 与 0.05 之间\nC. 甲市支持的期望频数为 105，χ² 约 9.02，p 值约 0.0027，说明支持率相同的概率是 0.27%\nD. 甲市支持的期望频数为 105，χ² 约 9.02，p 值小于 0.01，故拒绝两城市支持率相同的假设", back: "答案：D\n简析：甲市支持人数的期望频数为 200 乘 210 除以 400 等于 105，χ²=2 乘 (15²/105)+2 乘 (15²/95) 约 9.02，df=(2-1)(2-1)=1，p 值约 0.0027 小于 0.01，故拒绝两城市支持率相同的假设，D 正确，期望频数应由行合计乘列合计再除以总数得到（105 等），四个格子都取 100 会得到 χ² = 4 × 20² ÷ 100 = 16.0，无论 df 取 1 还是 2 都超过 0.01 的临界值，2×2 表的自由度为 1 而不是 3，0.0027 是 p 值而不是支持率相同的概率\n\n正确选项：甲市支持的期望频数为 105，χ² 约 9.02，p 值小于 0.01，故拒绝两城市支持率相同的假设", source: "ai-mcq", verified: true },
  { id: "stats-scenario-047", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某公司用广告投入 x（万元）预测月销售额 y（万元），得到 ŷ=40+3.5x，数据的 x 范围为 2 到 10 万元，r²=0.86，残差图没有明显弯曲。某月投入 6 万元，实际销售额为 68 万元。关于该月数据与模型的用法，最恰当的是\nA. 预测值为 61 万元，残差为 -7 万元，说明实际值低于模型的预测值\nB. 预测值为 68 万元，残差为 7 万元，因为残差是实际销售额与投入之差\nC. 预测值为 61 万元，残差为 +7 万元；若用 x=20 预测则属于外推，不可靠\nD. 预测值为 61 万元，残差为 +7 万元；且因 r² 较大，用 x=20 预测同样可靠", back: "答案：C\n简析：ŷ=40+3.5 乘 6=61 万元，残差为 68-61=+7 万元，说明该月实际销售额高于预测；而数据中 x 只在 2 到 10 之间，取 x=20 属于外推，回归关系在数据范围之外未必成立，C 正确，残差正 7 而不是负 7，残差是实际值减预测值而不是实际值与投入之差，r² 大只说明范围内拟合较好，不能使外推可靠\n\n正确选项：预测值为 61 万元，残差为 +7 万元；若用 x=20 预测则属于外推，不可靠", source: "ai-mcq", verified: true },
  { id: "stats-scenario-048", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某连锁餐厅用门店面积 x（百平方米）预测月营业额 y（万元），输出为常数项 6.9、斜率 8.3、r=0.79、r²=0.624。其中一家老旧门店面积只有 3 百平方米、月营业额仅 5 万元（其余门店面积在 6 到 12 之间），去掉这家店后斜率变为 6.1、r² 变为 0.43。关于这些结果最恰当的是\nA. 斜率 8.3 表示面积每多 1 百平方米营业额平均提高 8.3 万元，该店影响较大\nB. r²=0.624 表示门店面积每增加 1 个单位，营业额平均提高约 0.624 万元\nC. r=0.79 表示门店面积可以解释营业额变异的 79%，其余部分来自其他因素\nD. 因为该店营业额最低，去掉它能提高 r²，所以在分析时应直接删除该店", back: "答案：A\n简析：斜率 8.3 表示门店面积每增加 1 百平方米月营业额平均提高 8.3 万元，而该店位于 x 的低端且明显低于整体趋势，去掉它后斜率由 8.3 降为 6.1、r² 由 0.624 降为 0.43，说明它对回归影响较大，应报告并检查，A 正确，r² 是解释的变异比例而不是营业额提高的百分比，r 等于 0.79 不等于可解释 79% 的变异，营业额低不能说明它是错误数据，而且正是它使 r² 由 0.43 升到 0.624，删掉它 r² 反而下降，随意删除会掩盖它对回归的影响\n\n正确选项：斜率 8.3 表示面积每多 1 百平方米营业额平均提高 8.3 万元，该店影响较大", source: "ai-mcq", verified: true },
  { id: "stats-scenario-049", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 3, front: "某细菌培养实验中记录时间 t（小时）与细菌数 y（个），y 随时间增长得越来越快。对 y 取自然对数后，log y 与 t 的散点图近似直线，回归方程为 log ŷ=2.10+0.35t，r²=0.98；而对 log y 与 log t 作图仍然明显弯曲。关于该模型，最恰当的是\nA. 应改用幂函数模型，因为只要同时对两个变量取对数就一定能把散点变成直线\nB. t 每增加 1 小时，y 约变为原来的 e^0.35≈1.42 倍，即近似指数增长\nC. 方程中的 0.35 表明 t 每增加 1 小时，y 就平均增加 0.35 个\nD. log y 与 t 的 r² 为 0.98，说明 y 与 t 的相关系数也约为 0.98", back: "答案：B\n简析：log y 对 t 呈直线说明 y 与 t 近似满足指数关系 y 约等于 e^2.10 乘 e^0.35t，t 每增加 1 小时 y 变为 e^0.35 约 1.42 倍，B 正确，log y 对 log t 仍弯曲说明不是幂函数模型，直线方程中的 0.35 是 log y 的增量而不是 y 的增量，log y 与 t 的 r² 不能当作 y 与 t 的相关系数\n\n正确选项：t 每增加 1 小时，y 约变为原来的 e^0.35≈1.42 倍，即近似指数增长", source: "ai-mcq", verified: true },
  { id: "stats-scenario-050", deck: "stats-scenario", category: "AP Stats · 情境题", difficulty: 4, front: "某研究者想检验某咖啡店顾客中女性比例是否为 0.5。实际样本 40 人中有 26 人，样本比例 p̂=0.65。在 p=0.5 的条件下模拟抽取 1000 个容量为 40 的样本，其中有 40 个 p̂ 不小于 0.65，有 40 个 p̂ 不大于 0.35。根据该模拟结果，最恰当的结论是\nA. 模拟 p 值约为 0.040，小于 0.05，有证据表明女性比例不是 0.5\nB. 模拟 p 值约为 0.080，说明女性比例为 0.5 的概率约为 8%\nC. 模拟中 p̂ 的均值约为 0.65，因为模拟是在观测到的样本比例 0.65 下进行的\nD. 模拟 p 值约为 0.080，大于 0.05，没有足够证据认为女性比例不是 0.5", back: "答案：D\n简析：模拟的两侧极端比例之和为 (40+40)/1000=0.080，大于 0.05，故没有足够证据拒绝 p=0.5，D 正确，0.040 只算了一侧，p 值是 H0 为真时出现当前或更极端结果的概率而不是 H0 为真的概率，模拟是在 p=0.5 条件下进行的，模拟中 p̂ 的均值应约为 0.5 而不是 0.65\n\n正确选项：模拟 p 值约为 0.080，大于 0.05，没有足够证据认为女性比例不是 0.5", source: "ai-mcq", verified: true },
];
